```cuda
template <int BLOCK_SIZE>
__global__ void MatrixMulCUDA(float *C, const float *A, const float *B,
                              int M, int N, int K, int blocksPerRow) {
    int bx = blockIdx.x % blocksPerRow;
    int by = blockIdx.x / blocksPerRow;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    double Csub = 0.0;

    for (int k0 = 0; k0 < K; k0 += BLOCK_SIZE) {
        int aCol = k0 + tx;
        As[ty][tx] = (row < M && aCol < K) ? A[(long long)row * K + aCol] : 0.0f;
        int bRow = k0 + ty;
        Bs[ty][tx] = (bRow < K && col < N) ? B[(long long)bRow * N + col] : 0.0f;
        __syncthreads();
        #pragma unroll
        for (int k = 0; k < BLOCK_SIZE; ++k)
            Csub += (double)As[ty][k] * (double)Bs[k][tx];
        __syncthreads();
    }
    if (row < M && col < N)
        C[(long long)row * N + col] = (float)Csub;
}
