64	// Helper functions and utilities to work with CUDA
65	#include <helper_cuda.h>
66	#include <helper_functions.h>
67	
68	// Total device buffer space (d_A + d_B + d_C) a single process may request.
69	static const unsigned long long kMaxDeviceBufferBytes = 512ull * 1024 * 1024; // 512 MiB
70	
71	/**
72	 * Matrix multiplication (CUDA Kernel) on the device: C = A * B
73	 * A is M x K, B is K x N, C is M x N (all row-major).
74	 * blocksPerRow is the number of thread blocks along the N dimension; the
75	 * 1D grid is decomposed as (row block, column block) inside the kernel so
76	 * that arbitrarily large M and N stay within grid dimension limits.
77	 *
78	 * The reduction is accumulated in double precision so that inputs with
79	 * large cancelling terms still match the double-precision CPU reference
80	 * within the required tolerance; the output itself is single precision.
81	 */
82	template <int BLOCK_SIZE>
83	__global__ void MatrixMulCUDA(float *C, const float *A, const float *B, int M, int N, int K, int blocksPerRow)
84	{
85	    // Decompose the 1D block index into 2D tile coordinates.
86	    int bx = blockIdx.x % blocksPerRow;
87	    int by = blockIdx.x / blocksPerRow;
88	
89	    // Thread index
90	    int tx = threadIdx.x;
91	    int ty = threadIdx.y;
92	
93	    // Global row/column of C computed by this thread.
94	    int row = by * BLOCK_SIZE + ty;
95	    int col = bx * BLOCK_SIZE + tx;
96	
97	    // Declaration of the shared memory arrays used to
98	    // store the sub-matrices of A and B
99	    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
100	    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];
101	
102	    // Csub is used to accumulate the element of the block
103	    // sub-matrix that is computed by the thread
104	    double Csub = 0.0;
105	
106	    // Loop over all the sub-matrices of A and B required to compute
107	    // the block sub-matrix, including a partial tail tile when K is
108	    // not a multiple of BLOCK_SIZE.
109	    for (int k0 = 0; k0 < K; k0 += BLOCK_SIZE) {
110	        // Load the tiles from device memory to shared memory; each
111	        // thread loads one element of each matrix.  Elements outside
112	        // the matrix bounds are zero-filled so partial edge tiles
113	        // contribute nothing to the result.
114	        int aCol = k0 + tx;
115	        As[ty][tx] = (row < M && aCol < K) ? A[static_cast<long long>(row) * K + aCol] : 0.0f;
116	
117	        int bRow = k0 + ty;
118	        Bs[ty][tx] = (bRow < K && col < N) ? B[static_cast<long long>(bRow) * N + col] : 0.0f;
119	
120	        // Synchronize to make sure the matrices are loaded
121	        __syncthreads();
122	
123	        // Multiply the two matrices together;
124	        // each thread computes one element
125	        // of the block sub-matrix
126	#pragma unroll
127	
128	        for (int k = 0; k < BLOCK_SIZE; ++k) {
129	            Csub += static_cast<double>(As[ty][k]) * static_cast<double>(Bs[k][tx]);
130	        }
131	
132	        // Synchronize to make sure that the preceding
133	        // computation is done before loading two new
134	        // sub-matrices of A and B in the next iteration
135	        __syncthreads();
136	    }
137	
138	    // Write the block sub-matrix to device memory;
139	    // each thread writes one element
140	    if (row < M && col < N) {
141	        C[static_cast<long long>(row) * N + col] = static_cast<float>(Csub);
142	    }
143	}
